/* v111 السحب فوق الشريط السفلي يمرّر المحتوى (داخل إطار الجوال حيث يكون التمرير داخليًا) */
(function () {
  const scroller = function (dock) {
    let x = dock && dock.parentElement && dock.parentElement.querySelector('.t2-main');
    while (x && x !== document.body && x !== document.documentElement) {
      const o = getComputedStyle(x).overflowY;
      if ((o === 'auto' || o === 'scroll') && x.scrollHeight > x.clientHeight + 2) return x;
      x = x.parentElement;
    }
    return null;
  };
  let st = null;
  document.addEventListener('touchstart', function (ev) {
    const d = ev.target.closest && ev.target.closest('#pv-host .t2-dock'); if (!d) { st = null; return; }
    const sc = scroller(d); st = sc ? { sc: sc, y: ev.touches[0].clientY, moved: false } : null;
  }, { passive: true });
  document.addEventListener('touchmove', function (ev) {
    if (!st) return; const y = ev.touches[0].clientY, dy = st.y - y;
    if (Math.abs(dy) > 3) { st.moved = true; st.sc.scrollTop += dy; st.y = y; if (ev.cancelable) ev.preventDefault(); }
  }, { passive: false });
  document.addEventListener('touchend', function () { st = null; }, { passive: true });
  document.addEventListener('wheel', function (ev) {
    const d = ev.target.closest && ev.target.closest('#pv-host .t2-dock'); if (!d) return;
    const sc = scroller(d); if (!sc) return; sc.scrollTop += ev.deltaY; ev.preventDefault();
  }, { passive: false });
})();

