/* ================= فيلمُ التدشين — مرّةً واحدة بعدَ أوّلِ تفعيل، بلا تخطٍّ ================= */
let SHOWN = false;
async function maybeLaunch(ctx) {
  if (SHOWN) return;
  let m;
  try { m = await loadMem(true); } catch (err) { return; }
  if (!m || !m.exists || !m.launch_pending) return;
  SHOWN = true;
  launchFilm(m, function () { if (ctx && ctx.go) ctx.go('home'); });
}

